ids = ["LY-242","LY-243","LY-244","LY-245","LY-246","LY-249","LY-250","LY-251",
       "LY-252","LY-253","LY-254","LY-255","LY-259","LY-301","LY-304","LY-305",
       "LY-306","LY-307","LY-309","LY-311"]
assert set(ids) == set(P), (set(ids) ^ set(P))

written = 0
for cid in ids:
    rec = {"case_id": cid, "prediction_text": P[cid]["prediction_text"],
           "basis": P[cid]["basis"], "confidence": P[cid]["confidence"],
           "trigger": P[cid]["trigger"]}
    with open(os.path.join(OUT, cid + ".json"), "w", encoding="utf-8") as f:
        json.dump(rec, f, ensure_ascii=False, indent=1)
    written += 1

# 落盘后逐件精确回读自验（只按本批 id 清单逐件打开，不做目录列表/计数）
ok = 0
counts = {"changed_main": 0, "reserve_used": 0, "disputed": 0}
for cid in ids:
    with open(os.path.join(OUT, cid + ".json"), encoding="utf-8") as f:
        r = json.load(f)
    assert r["case_id"] == cid
    assert set(r) == {"case_id", "prediction_text", "basis", "confidence", "trigger"}
    assert isinstance(r["confidence"], float) and 0.0 <= r["confidence"] <= 1.0
    t = r["trigger"]
    assert set(t) == {"changed_main", "reserve_used", "disputed", "reason"}
    assert all(isinstance(t[k], bool) for k in ("changed_main", "reserve_used", "disputed"))
    assert isinstance(t["reason"], str)
    for k in counts:
        counts[k] += int(t[k])
    ok += 1
print("written:", written, "verified:", ok, "trigger_counts:", counts)
